const {chromium}=require('playwright');const assert=require('node:assert/strict');
async function main(){const {createServer}=await import('vite');const server=await createServer({server:{host:'127.0.0.1',port:4298,strictPort:true}});await server.listen();const browser=await chromium.launch({executablePath:process.env.PLAYWRIGHT_EXECUTABLE_PATH||undefined,args:['--no-sandbox']});
try{for(const width of [390,768,1024,1440])for(const theme of ['light','dark']){const page=await browser.newPage({viewport:{width,height:900},colorScheme:theme});const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:4298/#/app/reconciliation');
const choose=async name=>{if(width<1024)await page.getByRole('button',{name:/Choose statement transaction/}).click();await page.getByRole('button',{name:new RegExp(name)}).click();};
await choose('MIM CONSTRUCTION PAYMENT');assert.equal(await page.getByRole('button',{name:'Match transaction',exact:true}).isDisabled(),true);
await page.getByRole('textbox',{name:/Amount/}).fill('18000');assert.equal(await page.getByRole('button',{name:'Save preview correction'}).isDisabled(),true);
await page.getByRole('textbox',{name:/Why change this/}).fill('Checked source receipt');await page.getByRole('button',{name:'Save preview correction'}).click();await page.getByRole('button',{name:'Match transaction',exact:true}).click();
await choose('SHOP RENT OCTOBER');await page.getByRole('button',{name:'Match transaction',exact:true}).click();
for(const name of ['CASH DEPOSIT NAWABPUR','BANK CHARGE VAT','INTEREST CREDIT']){await choose(name);await page.getByRole('button',{name:'Create sample transaction'}).click();}
await page.getByRole('button',{name:'Save reviewed preview'}).click();await page.getByRole('button',{name:/Open PREVIEW-/}).click();await page.getByRole('dialog').getByText('Sample statement review').waitFor();await page.getByRole('dialog').getByRole('button',{name:'Close',exact:true}).click();
await page.getByRole('button',{name:'Statement import'}).click();await page.getByRole('dialog').getByText(/PDF reading is not connected/).waitFor();await page.getByRole('button',{name:'Back to sample transactions'}).click();
const download=page.waitForEvent('download');await page.getByRole('button',{name:'Export',exact:true}).click();assert.match((await download).suggestedFilename(),/reconciliation.*csv/);
assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2),'bank screen fits '+width);
await page.goto('http://127.0.0.1:4298/#/app/finance');await page.getByRole('tab',{name:'Cash Sessions',exact:true}).click();await page.getByRole('button',{name:'Count / close cash session'}).click();
let dialog=page.getByRole('dialog');assert.equal(await dialog.getByRole('button',{name:'Close session',exact:true}).isDisabled(),true);await dialog.getByRole('textbox',{name:'Cash counted'}).fill('48200');assert.equal(await dialog.getByRole('button',{name:'Close session',exact:true}).isDisabled(),true);await dialog.getByRole('textbox',{name:/Note/}).fill('Recounted, short 50');await dialog.getByRole('button',{name:'Save count',exact:true}).click();await page.getByText(/Last count:/).waitFor();await page.getByRole('button',{name:'Count / close cash session'}).click();await dialog.getByRole('button',{name:'Close session',exact:true}).click();await page.getByRole('button',{name:'Open cash session',exact:true}).last().click();await dialog.getByRole('textbox',{name:/Opening cash/}).fill('1500');await dialog.getByRole('button',{name:'Open session',exact:true}).click();await page.getByRole('button',{name:'Count / close cash session'}).click();await dialog.getByText('৳1,500',{exact:true}).first().waitFor();assert.equal(await dialog.getByRole('textbox',{name:'Cash counted'}).inputValue(),'');
const bounds=await dialog.boundingBox();assert.ok(bounds.x>=0&&bounds.x+bounds.width<=width+2,'cash dialog fits');assert.deepEqual(errors,[]);await page.close();}
console.log('Bank mismatch, correction validation, review history, export, import honesty; cash count/save/close/new opening passed at four widths in both themes');}finally{await browser.close();await server.close();}}
main().catch(e=>{console.error(e);process.exitCode=1;});
